def busqueda_binaria(arr, objetivo):
    izq, der = 0, len(arr) - 1
    while izq <= der:
        medio = (izq + der) // 2
        if arr[medio] == objetivo:
            return medio
        if arr[medio] < objetivo:
            izq = medio + 1
        else:
            der = medio - 1
    return -1

def contar_divisiones(n):
    pasos = 0
    while n > 1:
        n //= 2
        pasos += 1
    return pasos

def factorial(n):
    if n == 0:  # base case
        return 1
    else:
        return n * factorial(n - 1)  # recursive call

